"""Build the JVM test fixture DB from the real publication schema + seed.

Usage: python tests/fixtures/make_demo_places_db.py
Output: android/app/src/test/resources/demo_places.sqlite (gitignored if
large; small enough to commit — regenerated by this script).
"""
from __future__ import annotations

import sqlite3
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent.parent
OUT = ROOT / "android" / "app" / "src" / "test" / "resources" / "demo_places.sqlite"


def main() -> None:
    if OUT.exists():
        OUT.unlink()
    con = sqlite3.connect(str(OUT))
    con.execute("PRAGMA foreign_keys = ON;")
    con.executescript((ROOT / "content" / "schema" / "publication_schema.sql").read_text(encoding="utf-8"))
    con.executescript((ROOT / "content" / "seed" / "seed_demo.sql").read_text(encoding="utf-8"))
    con.commit()
    n_places = con.execute("SELECT COUNT(*) FROM places").fetchone()[0]
    n_fts = con.execute("SELECT COUNT(*) FROM place_search").fetchone()[0]
    hit = con.execute(
        "SELECT place_id FROM place_search WHERE place_search MATCH ?",
        ("Mahabodhi",),
    ).fetchall()
    con.close()
    print(f"places={n_places} fts={n_fts} probe={hit}")
    assert n_places >= 10 and n_fts >= 10 and hit, "fixture build failed"


if __name__ == "__main__":
    main()
